7. Rode o pipeline completo sobre o CSV sintético e imprima uma tabela final com nome_padronizado, logradouro_padronizado, bairro_padronizado e flag_revisao.

<b>💻 Código inicial</b>
<pre>import re
from rapidfuzz import process, fuzz

def limpar(t):
    t = t.lower().strip()
    t = re.sub(r&#x27;[^a-z0-9çãáéíóúâêôõü. ]&#x27;, &#x27; &#x27;, t)
    return re.sub(r&#x27;\s+&#x27;, &#x27; &#x27;, t).strip()

TIPO_LOGRADOURO = {&#x27;r&#x27;: &#x27;rua&#x27;, &#x27;r.&#x27;: &#x27;rua&#x27;, &#x27;av&#x27;: &#x27;avenida&#x27;, &#x27;av.&#x27;: &#x27;avenida&#x27;}
PARTICULAS = {&#x27;de&#x27;, &#x27;da&#x27;, &#x27;do&#x27;, &#x27;das&#x27;, &#x27;dos&#x27;}
BAIRROS_REF = [&#x27;jardim paulista&#x27;, &#x27;vila madalena&#x27;, &#x27;pinheiros&#x27;, &#x27;moema&#x27;]

def segmentar_nome(tokens):
    primeiro = tokens[0]
    resto = tokens[1:]
    sobrenome = []
    for tk in resto:
        sobrenome.append(tk)
    return primeiro, &#x27; &#x27;.join(sobrenome)

def padronizar_logradouro(tokens):
    if tokens and tokens[0] in TIPO_LOGRADOURO:
        tokens[0] = TIPO_LOGRADOURO[tokens[0]]
    return &#x27; &#x27;.join(tokens)

def verificar_bairro(bairro, limiar=80):
    match, score, _ = process.extractOne(bairro, BAIRROS_REF, scorer=fuzz.ratio)
    return match, score &lt; limiar

assert limpar(&#x27; Maria   DA Silva  &#x27;) == &#x27;maria da silva&#x27;
assert padronizar_logradouro([&#x27;r.&#x27;, &#x27;das&#x27;, &#x27;flores&#x27;]) == &#x27;rua das flores&#x27;
nome, sob = segmentar_nome(limpar(&#x27;maria da silva neto&#x27;).split())
assert nome == &#x27;maria&#x27; and sob == &#x27;da silva neto&#x27;
bairro_corrigido, flag = verificar_bairro(&#x27;jardim paulsta&#x27;)
